/**
 * 苏格拉底式 5 阶段配置
 *  - getPhaseAngle:     每阶段的"追问角度"指令
 *  - getPhaseTemperature: 每阶段的 LLM temperature
 *  - getPhaseScaffolding: 困难/阶段开端时的脚手架 system prompt
 */

function getPhaseAngle(phase) {
  const angles = {
    define: '帮用户厘清"到底在纠结什么"——表面决定背后的真实矛盾。不要评论用户的表达方式,直接追问内心最真实的拉扯是什么。',
    stance: '帮用户把支持和反对的理由都说清楚,逼他看到硬币的两面。理由笼统时(如"为了更好的发展"),追问具体画面。',
    premortem: '逼用户直面回避的最坏结果。假设3年后这个决定变成灾难,最可能的原因是什么(不是因为运气)?然后反过来,假设不变,3年后最后悔的是什么?',
    blindspot: '用镜像问题让用户自己发现认知偏差。基于用户之前的原话,构造反直觉问题。绝对不说偏差名称。如果用户很坚定,问"第三条路"或"如果两个都不选呢?"',
    future: '拉长时间尺度,帮用户跳出当下情绪。温和地问:10年后的你回看今天,会觉得现在纠结的事有多重要?不要施压,不要替用户总结。'
  };
  return angles[phase] || angles.define;
}

function getPhaseTemperature(phase) {
  const temps = { define: 0.7, stance: 0.65, premortem: 0.5, blindspot: 0.5, future: 0.75 };
  return temps[phase] || 0.6;
}

function buildScaffoldPrompt(phaseTheme, inspirationPool) {
  return `用户处于阶段开端或表现出困难信号,需要思考抓手。请把回复严格分成两部分:

【主追问】(用户主屏直接看到):
- 一句温和的承认("这个问题确实不好想"或类似)
- 一个针对用户具体情境的简短入门追问

【脚手架】(必须用 [SCAFFOLD] 和 [/SCAFFOLD] marker 包裹,前端会折叠):
- 2-3 个针对用户的思考方向
- 结尾问"哪个角度对你最有感觉?"

🔴【极重要 - 维度本地化原则,必须遵守】:
1. **维度名必须从用户原话中提取具体词或场景**,不是套用通用类别
2. **禁止**使用"经济维度""成长维度""时间维度""身份维度""沉没成本""确认偏误"等抽象类别名作为维度名(它们是你内部的思考分类,不能直接出现在用户看到的内容里)
3. 直接命名用户在意的具体担忧、矛盾、感受
4. 每个维度后跟一个针对该维度的具体追问,引用用户原话

举例对比(这是 stance 阶段,用户说"想辞职去做设计师,但怕养不活自己"):
❌ 通用差(完全不能这样写):
- 经济维度:你的收入和储蓄够撑多久?
- 成长维度:做设计师能给你带来什么?

✅ 本地化好(必须这样写):
- "养不活自己"具体怕什么:是怕没钱付房租,还是怕父母看不起?
- 设计师这条路你想过多远:打零工接单,还是开自己的工作室?
- 现在的工作里你最舍不得放下的是什么?

阶段思考主题:${phaseTheme}

可参考的思考切入点(仅作启发,绝对不要直接照搬作维度名):
${inspirationPool}

格式示例(注意:维度内容是占位符,实际必须基于用户原话生成):
"<温和承认句>。<针对用户原话的入门追问>?

[SCAFFOLD]
如果想从更多角度切入,可以从这几个想想:
- <从用户原话提取的具体词或场景>:<针对它的具体追问>?
- <第二个本地化的具体维度>:<具体追问>?
- <第三个本地化的具体维度>:<具体追问>?

哪个角度对你最有感觉?
[/SCAFFOLD]"`;
}

function getPhaseScaffolding(phase) {
  const scaffolds = {
    define: buildScaffoldPrompt(
      '帮用户找到表面决定背后的真实矛盾',
      `- 表面决定 vs 真实需求(用户说想做X,真的想要X还是X所代表的状态?)
- 时间触发(为什么是现在冒出来,什么事让你开始想?)
- 身份切换(改变后的"我"是谁?现在的"我"是谁?)
- 替代方案(除了"做"和"不做"还有什么第三种可能?)
- 核心矛盾(到底是什么 vs 什么的拉扯?)`
    ),
    stance: buildScaffoldPrompt(
      '帮用户把支持和反对的力量都说清楚',
      `- 推动改变的渴望(具体是什么在拉你往前?)
- 拉住不变的恐惧(具体在怕什么?)
- 价值 vs 代价(为了什么愿意失去什么?)
- 短期感受 vs 长期意义
- 自己的需求 vs 他人的期待`
    ),
    premortem: buildScaffoldPrompt(
      '逼用户直面回避的最坏结果',
      `- 改变后最坏的具体场景(必须具体,不是"失败"二字)
- 不变后最深的遗憾(具体哪一刻你会最后悔?)
- 可逆性(错了能多快回头?代价多大?)
- 应对预案(最坏发生时你怎么办?)
- 你最害怕的那个具体画面`
    ),
    blindspot: buildScaffoldPrompt(
      '让用户自己发现认知偏差(注意:不要说出"沉没成本""确认偏误"这种术语)',
      `- 假如过去投入全部清零,还会选这条路吗?
- 你最近主动找过反对这个决定的理由吗?
- 两个选项之外有没有第三条路?
- 怎么说服自己选另一边?(为反方做最有力的辩护)
- 有什么是你一直不敢看的真相或恐惧?`
    ),
    future: buildScaffoldPrompt(
      '拉长时间尺度,帮用户跳出当下',
      `- 10年后的你怎么看今天的纠结?
- 80岁的你回看会觉得什么重要?
- 老了之后更后悔"做了失败"还是"从没试过"?
- 这个选择会让你成为什么样的人?那是你想成为的人吗?
- 给5年后的自己留一句话,你会说什么?`
    ),
  };
  return scaffolds[phase] || '';
}

module.exports = {
  getPhaseAngle,
  getPhaseTemperature,
  getPhaseScaffolding,
};
